class QuotaError(RuntimeError):
    pass


class OverpassError(RuntimeError):
    pass


class RateLimiter:
    """Mindestabstand zwischen Anfragen je Dienst – thread-sicher, Antwortzeit wird angerechnet."""

    def __init__(self, per_min: float):
        self._lock = threading.Lock()
        self._next = 0.0
        self.set(per_min)

    def set(self, per_min: float) -> None:
        self.interval = 60.0 / max(1.0, float(per_min))

    def wait(self) -> None:
        with self._lock:
            now = time.monotonic()
            if self._next > now:
                time.sleep(self._next - now)
                now = time.monotonic()
            self._next = now + self.interval


LIM_ORS_GEO = RateLimiter(95)   # HeiGIT Standard: 100 Geocoding-Anfragen/Minute
LIM_OSM = RateLimiter(57)       # Nominatim: max. 1 Anfrage/Sekunde
LIM_OVP = RateLimiter(30)       # Overpass: fair use (schonend)
LIM_PHOTON = RateLimiter(50)    # Photon (komoot): fair use


def _read_json(path: Path) -> dict:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}


USE_LOCAL_CACHE = False   # Standard: nichts auf der Festplatte – Speicher ist die Adressdatei (Upload/Download)
_MEM_CACHE: dict = {}     # Arbeitsspeicher für den laufenden Durchlauf (vorbefüllt aus der Adressdatei)


def load_cache(name: str) -> dict:
    """Arbeitsspeicher (+ optional lokaler Cache inkl. alter Ordner). Erfolgreiche Treffer gehen nie verloren."""
    data = dict(_MEM_CACHE.get(name, {}))
    if not USE_LOCAL_CACHE:
        return data
    for k, v in _read_json(CACHE_DIR / name).items():
        data.setdefault(k, v)
    extra = [d / name for d in LEGACY_CACHE_DIRS if d != CACHE_DIR] + [CACHE_DIR / (name + ".bak")]
    for path in extra:
        if not path.exists():
            continue
        for k, v in _read_json(path).items():
            cur = data.get(k)
            if cur is None or (isinstance(cur, dict) and cur.get("fail") and isinstance(v, dict) and not v.get("fail")):
                data[k] = v
    return data


def backup_cache(name: str) -> None:
    if not USE_LOCAL_CACHE:
        return
    src = CACHE_DIR / name
    if src.exists():
        try:
            (CACHE_DIR / (name + ".bak")).write_bytes(src.read_bytes())
        except Exception:
            pass


def cache_info() -> str:
    geo = _read_json(CACHE_DIR / "geo_cache.json") if USE_LOCAL_CACHE else _MEM_CACHE.get("geo_cache.json", {})
    ok = sum(1 for v in geo.values() if isinstance(v, dict) and not v.get("fail"))
    return f"{ok} Adressen gefunden · {len(geo) - ok} offen/fehlgeschlagen"


def save_cache(name: str, obj: dict) -> None:
    _MEM_CACHE[name] = dict(obj)
    if not USE_LOCAL_CACHE:
        return
    try:
        CACHE_DIR.mkdir(parents=True, exist_ok=True)
        tmp = CACHE_DIR / (name + ".tmp")
        tmp.write_text(json.dumps(obj, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")
        tmp.replace(CACHE_DIR / name)
    except Exception:
        pass


def haversine(lat1, lon1, lat2, lon2):
    lat1, lon1, lat2, lon2 = map(np.radians, (lat1, lon1, lat2, lon2))
    a = np.sin((lat2 - lat1) / 2) ** 2 + np.cos(lat1) * np.cos(lat2) * np.sin((lon2 - lon1) / 2) ** 2
    return 2 * 6371.0 * np.arcsin(np.sqrt(a))


def _txt(v) -> str:
    return "" if v is None or (isinstance(v, float) and np.isnan(v)) or v is pd.NA else re.sub(r"\s+", " ", str(v)).strip()


def addr_key(street, plz, city) -> str:
    return "|".join(_txt(x).lower() for x in (street, plz, city))


def ors_request(session, method: str, service: str, key: str, profile: str = "", **kw):
    """HeiGIT-Endpunkt zuerst, bei 404/405/Netzwerkfehler der alte ORS-Pfad; merkt sich den funktionierenden.
    Key als Authorization-Header, bei GET zusätzlich als api_key-Parameter."""
    templates = [t for t in dict.fromkeys([_ORS_WORKING.get(service), *ORS_ENDPOINTS[service]]) if t]
    headers = {"Authorization": key}
    if method == "GET":
        kw.setdefault("params", {})["api_key"] = key
    last = None
    for i, tpl in enumerate(templates):
        url = tpl.format(host=ORS_HOST.rstrip("/"), profile=profile)
        if service.startswith("geocode"):
            LIM_ORS_GEO.wait()
        try:
            r = session.request(method, url, headers=headers, **kw)
        except Exception as exc:
            last = exc
            continue
        if r.status_code in (404, 405) or (r.status_code >= 500 and i < len(templates) - 1):
            last = RuntimeError(f"{url}: HTTP {r.status_code}")
            continue
        _ORS_WORKING[service] = tpl
        rem = r.headers.get("x-ratelimit-remaining")
        if rem is not None:
            ORS_QUOTA[service] = (rem, r.headers.get("x-ratelimit-reset", ""))
        return r
    raise last or RuntimeError("OpenRouteService nicht erreichbar")


GEO_CACHE_VERSION = 4   # ältere Fehlschläge werden mit der verbesserten Suche automatisch erneut versucht
_LAYER_Q = {"address": "addr", "venue": "addr", "street": "street"}


def clean_street(s: str) -> str:
    """'Hauptstr. 12-14 (Hof)' → 'Hauptstraße 12'."""
    t = _txt(s)
    t = re.sub(r"\([^)]*\)", " ", t)                                    # Klammerzusätze
    t = re.sub(r"(?i)(\w)str\.?(?=\s|\d|$)", r"\1straße", t)            # Hauptstr. → Hauptstraße
    t = re.sub(r"(?i)\bstr\.?(?=\s|\d|$)", "Straße", t)                  # Str. → Straße
    t = re.sub(r"(?i)(\w)pl\.(?=\s|\d|$)", r"\1platz", t)                # Marktpl. → Marktplatz
    t = re.sub(r"(?i)([a-zäöüß])(\d)", r"\1 \2", t)                        # Straße5 → Straße 5
    t = re.sub(r"(\d+\s*[a-zA-Z]?)\s*[-–/+]\s*(?:\d+\s*[a-zA-Z]?|[a-zA-Z])\b", r"\1", t)   # 12-14, 12a-c → 12 / 12a
    t = re.split(r"\s+/\s+|;|\s+-\s+", t)[0]                             # Zusatzinfos abtrennen
    return re.sub(r"\s+", " ", t).strip(" ,.")


def clean_city(s: str) -> str:
    """'Neumünster OT Einfeld' → 'Neumünster', 'Hamburg (Altona)' → 'Hamburg'."""
    t = _txt(s)
    t = re.sub(r"\([^)]*\)", " ", t)
    t = re.split(r"(?i)\s+OT\s+|\s*/\s*|,", t)[0]
    return re.sub(r"\s+", " ", t).strip(" ,.")


def _pick_feature(feats: list, center) -> tuple[dict | None, str]:
    why = "kein Treffer" if not feats else ""
    for f in feats:
        props = f.get("properties") or {}
        q = _LAYER_Q.get(props.get("layer", ""))
        if not q:
            why = why or f"nur {props.get('layer', '?')}-Ebene"
            continue
        lon, lat = f["geometry"]["coordinates"][:2]
        if center and float(haversine(center[0], center[1], lat, lon)) > GEO_MAX_DEVIATION_KM:
            why = why or "zu weit vom PLZ-Gebiet"
            continue
        return {"lat": float(lat), "lon": float(lon), "q": q}, ""
    return None, why or "kein Treffer"


def _ors_json(session, service: str, key: str, params: dict):
    r = ors_request(session, "GET", service, key, params=params, timeout=25)
    if r.status_code in (401, 403, 429):
        hint = " (Tageskontingent aufgebraucht?)" if r.status_code in (403, 429) else " (API-Key ungültig?)"
        raise QuotaError(f"OpenRouteService Geocoding: HTTP {r.status_code}{hint} {r.text[:80]}")
    r.raise_for_status()
    return r.json().get("features") or []


def geocode_ors(session, key: str, street: str, plz: str, city: str, center=None, extended: bool = False):
    """Strukturierte Suche (1 Anfrage). extended=True: zusätzlich ohne Ort und als Freitext (bis 3 Anfragen).
    Standard ist sparsam, weil das ORS-Tageskontingent begrenzt ist; Nominatim/Straßenabgleich übernehmen den Rest."""
    params = {"address": street, "postalcode": plz, "country": "DE", "size": 3}
    if city:
        params["locality"] = city
    res, why = _pick_feature(_ors_json(session, "geocode", key, params), center)
    if res:
        return {**res, "src": "ors"}, ""
    if not extended:
        return None, why
    if city:   # Ortsname aus SAP oft abgekürzt/zusammengesetzt → nur PLZ
        params.pop("locality")
        res, why_b = _pick_feature(_ors_json(session, "geocode", key, params), center)
        if res:
            return {**res, "src": "ors"}, ""
    params = {"text": f"{street}, {plz} {city}", "boundary.country": "DEU", "size": 3}
    if center:
        params.update({"focus.point.lat": center[0], "focus.point.lon": center[1]})
    res, why2 = _pick_feature(_ors_json(session, "geocode_text", key, params), center)
    return ({**res, "src": "ors-text"}, "") if res else (None, why2 or why)


def geocode_nominatim(session, street: str, plz: str, city: str, center=None):
    variants = [{"street": street, "postalcode": plz, "countrycodes": "de"}]
    if city:
        variants.insert(0, {"street": street, "postalcode": plz, "city": city, "countrycodes": "de"})
    variants.append({"q": f"{street}, {plz} {city}".strip(), "countrycodes": "de"})
    for params in variants:
        for attempt in range(3):
            LIM_OSM.wait()
            r = session.get(NOMINATIM_URL, params={**params, "format": "jsonv2", "limit": 3}, timeout=25)
            if r.status_code != 429:
                break
            LIM_OSM.set(max(15.0, 60.0 / LIM_OSM.interval / 2))   # Tempo halbieren, kurz pausieren
            time.sleep(30 * (attempt + 1))
        if r.status_code in (403, 429):
            raise QuotaError(f"Nominatim: HTTP {r.status_code} (Sperre wegen zu vieler Anfragen – später erneut)")
        r.raise_for_status()
        for h in r.json() or []:
            rank = int(h.get("place_rank") or 0)
            q = "addr" if rank >= 28 else "street" if rank >= 26 else None
            if not q:
                continue
            lat, lon = float(h["lat"]), float(h["lon"])
            if center and float(haversine(center[0], center[1], lat, lon)) > GEO_MAX_DEVIATION_KM:
                continue
            return {"lat": lat, "lon": lon, "q": q, "src": "osm"}, ""
    return None, "OSM: kein Treffer"


# --- Abgleich abgekürzter SAP-Straßennamen mit echten OSM-Straßen -------------------------------------

_UML = str.maketrans({"ä": "ae", "ö": "oe", "ü": "ue", "ß": "ss", "é": "e"})


def _norm(s: str) -> str:
    return re.sub(r"[^a-z0-9 ]+", " ", _txt(s).lower().translate(_UML)).strip()


def split_street(raw: str) -> tuple[str, str]:
    """'BÜRGERM.HÖPPNER-STR.1A' → ('BÜRGERM.HÖPPNER-STR.', '1A'); 'POSTST.33/GR.BLEI.30' → ('POSTST.', '33')."""
    t = _txt(raw)
    m = re.search(r"(\d+)\s*([a-zA-Z](?![a-zA-Z]))?", t)
    if not m:
        return t, ""
    return t[:m.start()].strip(" ,"), (m.group(1) + (m.group(2) or "")).upper()


def _street_tokens(name: str) -> list:
    t = _txt(name).lower().translate(_UML)
    return [x for x in re.split(r"[^a-z0-9]+", t) if x]


def street_match_score(raw_name: str, cand: str) -> float:
    """Abkürzungs-tolerant: jedes SAP-Token ist Präfix/Teil der echten Schreibweise, in gleicher Reihenfolge.
    Tippfehler werden über einen unscharfen Vergleich abgefangen."""
    from difflib import SequenceMatcher
    toks = _street_tokens(raw_name)
    if not toks:
        return 0.0
    cn = _norm(cand)
    words = cn.split()
    compact = "".join(words)
    if not compact:
        return 0.0
    starts, i = set(), 0
    for w in words:
        starts.add(i)
        i += len(w)
    raw_compact = "".join(toks)
    if raw_compact == compact:
        return 2.0
    def _is_subseq(t, seg):
        it = iter(seg)
        return all(ch in it for ch in t)

    def _find(t, pos, need_start):
        j = compact.find(t, pos)
        while need_start and j >= 0 and j not in starts:
            j = compact.find(t, j + 1)
        if j >= 0:
            return j, len(t), 1.0
        if len(t) < 4:
            return -1, 0, 0.0
        for ws in sorted(x for x in starts if x >= pos):
            seg = compact[ws:ws + len(t) + 6]
            nxt = min([x for x in starts if x > ws] or [len(compact)])
            word = compact[ws:nxt]
            if t[:4] == word[:4] and _is_subseq(t, word):          # HUMMELB → hummelsbuettler
                return ws, nxt - ws, 0.9
            if len(t) >= 6 and SequenceMatcher(None, t, word[:len(t) + 1]).ratio() >= 0.85:   # BREITSCHEIT
                return ws, nxt - ws, 0.85
        return -1, 0, 0.0

    pos, first, matched, ok, qual = 0, None, 0, True, 1.0
    for t in toks:
        j, ln, q = _find(t, pos, first is None)
        if j < 0:
            ok = False
            break
        if first is None:
            first = j
        matched += ln
        qual = min(qual, q)
        pos = j + ln
    if ok and len(raw_compact) >= 4:
        return (min(1.0, matched / len(compact)) + (0.3 if first == 0 else 0.0) + 0.2) * qual
    if raw_compact[:1] != compact[:1] or len(raw_compact) < 5:
        return 0.0
    ratio = SequenceMatcher(None, raw_compact, compact[:len(raw_compact) + 3]).ratio()
    return ratio * 0.8 if ratio >= 0.8 else 0.0


def street_candidates(session, lat: float, lon: float, cache: dict) -> list:
    """Straßennamen (mit Straßenmitte) im Umkreis; probiert mehrere Overpass-Server, wartet bei Überlast."""
    key = f"{lat:.3f},{lon:.3f},{STREET_RADIUS_M}"
    if key in cache:
        return cache[key]
    q = (f'[out:json][timeout:90];way(around:{STREET_RADIUS_M},{lat:.5f},{lon:.5f})["highway"]["name"];'
         f'out tags center;')
    errors = []
    for attempt in range(2):
        for url in OVERPASS_URLS:
            LIM_OVP.wait()
            try:
                r = session.post(url, data={"data": q}, timeout=120 if url == OVERPASS_URLS[0] else 25)
            except Exception as exc:
                errors.append(f"{url.split('/')[2]}: {type(exc).__name__}")
                continue
            if r.status_code != 200:
                errors.append(f"{url.split('/')[2]}: HTTP {r.status_code}")
                if r.status_code in (429, 503, 504):
                    time.sleep(5)
                continue
            try:
                js = r.json()
            except Exception:
                errors.append(f"{url.split('/')[2]}: keine JSON-Antwort")
                continue
            els = js.get("elements", [])
            if not els and "error" in str(js.get("remark", "")).lower():
                errors.append(f"{url.split('/')[2]}: {str(js.get('remark'))[:60]}")
                continue
            seen, out = set(), []
            for el in els:
                name = (el.get("tags") or {}).get("name")
                c = el.get("center") or {}
                if name and name not in seen and "lat" in c:
                    seen.add(name)
                    out.append([name, c["lat"], c["lon"]])
            cache[key] = out
            return out
        time.sleep(15)
    raise OverpassError("Straßenliste nicht ladbar (" + "; ".join(errors[-3:]) + ")")


def _ovp_query(session, q: str) -> list:
    """Overpass-Abfrage über alle Server; liefert elements oder wirft OverpassError."""
    errors = []
    for url in OVERPASS_URLS:
        LIM_OVP.wait()
        try:
            r = session.post(url, data={"data": q}, timeout=90 if url == OVERPASS_URLS[0] else 25)
        except Exception as exc:
            errors.append(f"{url.split('/')[2]}: {type(exc).__name__}")
            continue
        if r.status_code != 200:
            errors.append(f"{url.split('/')[2]}: HTTP {r.status_code}")
            if r.status_code in (429, 503, 504):
                time.sleep(5)
            continue
        try:
            js = r.json()
        except Exception:
            errors.append(f"{url.split('/')[2]}: keine JSON-Antwort")
            continue
        if not js.get("elements") and "error" in str(js.get("remark", "")).lower():
            errors.append(f"{url.split('/')[2]}: {str(js.get('remark'))[:60]}")
            continue
        return js.get("elements", [])
    raise OverpassError("Overpass nicht erreichbar (" + "; ".join(errors[-3:]) + ")")


def _el_latlon(el):
    if "lat" in el:
        return float(el["lat"]), float(el["lon"])
    c = el.get("center") or {}
    return (float(c["lat"]), float(c["lon"])) if "lat" in c else None


def geocode_photon(session, street: str, plz: str, city: str, center=None):
    """Photon (komoot, OSM-basiert): kein Key, kein Tageskontingent. Rückgabe (Treffer, Grund)."""
    params = {"q": f"{street}, {plz} {city}".strip(" ,"), "limit": 5, "lang": "de"}
    if center:
        params.update({"lat": round(center[0], 4), "lon": round(center[1], 4)})
    for attempt in range(2):
        LIM_PHOTON.wait()
        r = session.get(PHOTON_URL, params=params, timeout=25)
        if r.status_code not in (429, 502, 503, 504):
            break
        time.sleep(10)
    if r.status_code in (403, 429):
        raise QuotaError(f"Photon: HTTP {r.status_code}")
    r.raise_for_status()
    _, hn = split_street(street)
    best, best_q = None, None
    for f in r.json().get("features") or []:
        p = f.get("properties") or {}
        lon, lat = f["geometry"]["coordinates"][:2]
        if center and float(haversine(center[0], center[1], lat, lon)) > GEO_MAX_DEVIATION_KM:
            continue
        if plz and p.get("postcode") and str(p["postcode"])[:5] != str(plz)[:5]:
            continue
        typ = p.get("type")
        if typ == "house" or p.get("housenumber"):
            same_hn = not hn or re.sub(r"\D", "", str(p.get("housenumber", ""))) == re.sub(r"\D", "", hn)
            q = "addr" if same_hn else "street"
        elif typ == "street" or p.get("osm_key") == "highway":
            q = "street"
        else:
            continue
        if best is None or (q == "addr" and best_q != "addr"):
            best, best_q = {"lat": float(lat), "lon": float(lon), "q": q, "src": "photon"}, q
            if q == "addr":
                break
    return (best, "") if best else (None, "Photon: kein Treffer")


def hn_of(street: str) -> str:
    return split_street(street)[1]


def geocode_overpass(session, street: str, center, radius_m: int = 6000):
    """Adresse direkt in OpenStreetMap: Gebäude/Knoten mit addr:street + addr:housenumber im Umkreis des PLZ-Zentrums.
    Ohne Tageskontingent. Fallback: Mitte der Straße. Rückgabe (Treffer, Grund)."""
    if not center:
        return None, "Overpass: kein PLZ-Zentrum"
    name, hn = split_street(street)
    name = re.sub(r"\s+", " ", name).strip(" ,.")
    if not name:
        return None, "Overpass: keine Straße"
    esc_name = name.replace("\\", "").replace('"', '\\"')
    lat, lon = center
    if hn:
        m = re.match(r"(\d+)\s*([a-zA-Z]?)", hn)
        num, let = m.group(1), m.group(2)
        hn_re = f"^{num} *{let}$" if let else f"^{num}([^0-9].*)?$"
        q = (f'[out:json][timeout:40];nwr(around:{radius_m},{lat:.5f},{lon:.5f})'
             f'["addr:street"="{esc_name}"]["addr:housenumber"~"{hn_re}",i];out center 5;')
        els = _ovp_query(session, q)
        pts = [p for p in (_el_latlon(e) for e in els) if p]
        if pts:
            p = min(pts, key=lambda x: float(haversine(lat, lon, x[0], x[1])))
            return {"lat": p[0], "lon": p[1], "q": "addr", "src": "osm-overpass"}, ""
    q = (f'[out:json][timeout:40];way(around:{radius_m},{lat:.5f},{lon:.5f})'
         f'["highway"]["name"="{esc_name}"];out center 10;')
    pts = [p for p in (_el_latlon(e) for e in _ovp_query(session, q)) if p]
    if pts:
        p = min(pts, key=lambda x: float(haversine(lat, lon, x[0], x[1])))
        return {"lat": p[0], "lon": p[1], "q": "street", "src": "osm-overpass-strasse"}, ""
    return None, "Overpass: Straße nicht in OSM gefunden"


def resolve_street(session, raw_street: str, center, street_cache: dict):
    """Liefert (echter Straßenname, Hausnummer, Straßenmitte) oder None."""
    if not center:
        return None
    name, hn = split_street(raw_street)
    if not _street_tokens(name):
        return None
    best, bs = None, 0.0
    for cand, clat, clon in street_candidates(session, center[0], center[1], street_cache):
        sc = street_match_score(name, cand)
        if sc > bs:
            best, bs = (cand, clat, clon), sc
    if not best or bs < 0.55:
        return None
    return best[0], hn, (best[1], best[2])


def connection_test(key: str) -> list:
    """Prüft jeden Dienst mit der Depot-Adresse und liefert (Dienst, Status, Detail)."""
    import requests
    sess = requests.Session()
    sess.headers["User-Agent"] = HTTP_UA
    rows = []

    def run(name, fn):
        t0 = time.time()
        try:
            status, detail = fn()
        except Exception as exc:
            status, detail = "Fehler", f"{type(exc).__name__}: {str(exc)[:160]}"
        rows.append({"Dienst": name, "Status": status, "Detail": detail, "Sek.": round(time.time() - t0, 1)})

    def ors_geo():
        if not key:
            return "übersprungen", "kein API-Key"
        r = ors_request(sess, "GET", "geocode", key, params={"address": "Am Heisterbusch 24", "postalcode": "19246", "country": "DE", "size": 1}, timeout=25)
        f = (r.json().get("features") or [{}])[0] if r.ok else {}
        return f"HTTP {r.status_code}", f"{r.url.split('?')[0]} · layer={(f.get('properties') or {}).get('layer')} · {r.text[:120] if not r.ok else ''}"

    def ors_mat():
        if not key:
            return "übersprungen", "kein API-Key"
        body = {"locations": [[DEPOT_LATLON[1], DEPOT_LATLON[0]], [10.0, 53.55]], "metrics": ["distance", "duration"], "units": "km"}
        r = ors_request(sess, "POST", "matrix", key, profile="driving-hgv", json=body, timeout=60)
        return f"HTTP {r.status_code}", (str(r.json().get("distances"))[:80] if r.ok else r.text[:160])

    def osm():
        r = sess.get(NOMINATIM_URL, params={"street": "Am Heisterbusch 24", "postalcode": "19246", "countrycodes": "de", "format": "jsonv2", "limit": 1}, timeout=25)
        js = r.json() if r.ok else []
        return f"HTTP {r.status_code}", (f"{len(js)} Treffer · rank {js[0].get('place_rank')} · {js[0].get('display_name', '')[:80]}" if js else r.text[:160])

    run("ORS Adresssuche", ors_geo)
    run("ORS Matrix (LKW)", ors_mat)
    run("Nominatim (OSM)", osm)

    def photon():
        r = sess.get(PHOTON_URL, params={"q": "Am Heisterbusch 24, 19246 Lüttow-Valluhn", "limit": 1}, timeout=25)
        f = (r.json().get("features") or [{}])[0] if r.ok else {}
        p = f.get("properties") or {}
        return f"HTTP {r.status_code}", (f"{p.get('type')} · {p.get('street')} {p.get('housenumber', '')} · {p.get('city')} · "
                                         f"{(f.get('geometry') or {}).get('coordinates')}" if r.ok else r.text[:160])

    run("Photon (komoot)", photon)
    for url in OVERPASS_URLS:
        def ovp(url=url):
            q = f'[out:json][timeout:30];way(around:800,{DEPOT_LATLON[0]},{DEPOT_LATLON[1]})["highway"]["name"];out tags center;'
            r = sess.post(url, data={"data": q}, timeout=60 if url == OVERPASS_URLS[0] else 20)
            js = r.json() if r.ok and r.headers.get("content-type", "").startswith("application/json") else {}
            names = sorted({(e.get("tags") or {}).get("name") for e in js.get("elements", [])} - {None})
            return f"HTTP {r.status_code}", (f"{len(names)} Straßen: {', '.join(names[:5])}" if js else r.text[:160])
        run(f"Overpass {url.split('/')[2]}", ovp)
    return rows


def geocode_addresses(df: pd.DataFrame, provider: str, key: str = "", retry_failed: bool = False,
                      progress: Callable[[int, int], None] | None = None,
                      osm_fallback: bool = True) -> tuple[pd.DataFrame, dict]:
    """provider: 'ors' | 'ovp' (nur Overpass, ohne Kontingent) | 'osm' (Nominatim) | 'cache'.
    Overpass läuft bei allen aktiven Quellen als letzte Stufe mit."""
    backup_cache("geo_cache.json")
    cache = load_cache("geo_cache.json")
    save_cache("geo_cache.json", cache)   # zusammengeführten Stand (inkl. alter Ordner) sofort festschreiben
    stats = {"neu": 0, "fehl": 0, "offen": 0, "abbruch": "", "gruende": {}}
    todo = []
    seen = set()
    fixed = df["gq"].isin(["datei", "manuell"]) if "gq" in df.columns else pd.Series(False, index=df.index)
    for (street, plz, city, plat, plon), is_fixed in zip(
            df[["Strasse", "Plz", "Ort", "lat", "lon"]].itertuples(index=False, name=None), fixed):
        k = addr_key(street, plz, city)
        if is_fixed or k in seen or not _txt(street):
            continue
        seen.add(k)
        c = cache.get(k)
        stale = c is not None and c.get("fail") and (retry_failed or c.get("v", 1) < GEO_CACHE_VERSION)
        if c is None or stale:
            center = None if plat is None or pd.isna(plat) else (float(plat), float(plon))
            todo.append((k, clean_street(street), _txt(plz), clean_city(city), center))
    stats["offen"] = len(todo)
    can_ors = provider == "ors" and bool(key)
    can_osm = provider == "osm" or (provider == "ors" and osm_fallback)
    if todo and provider in ("ors", "osm", "ovp", "photon"):
        # Pipeline: Hauptthread fragt ORS ab, ein zweiter Thread erledigt parallel OSM (Nominatim + Straßenabgleich)
        # für die ORS-Fehlschläge. Beide Dienste haben eigene Tempolimits → Gesamtzeit ≈ max statt Summe.
        import requests

        def new_session():
            ss = requests.Session()
            ss.headers["User-Agent"] = HTTP_UA
            return ss

        lock = threading.Lock()
        state = {"ors_dead": not can_ors, "can_osm": can_osm, "street_fail": 0, "done": 0,
                 "can_photon": provider != "ovp"}
        street_cache = load_cache("street_cache.json")
        jobs: queue.Queue = queue.Queue()

        def join(*parts):
            return " · ".join(x for x in parts if x)

        def store(k, res, why, retry_later=False):
            with lock:
                cache[k] = ({**res, "v": GEO_CACHE_VERSION} if res
                            else {"fail": True, "why": why, "v": GEO_CACHE_VERSION - (1 if retry_later else 0)})
                if res:
                    stats["neu"] += 1
                else:
                    stats["fehl"] += 1
                    stats["gruende"][why] = stats["gruende"].get(why, 0) + 1
                stats["offen"] -= 1
                state["done"] += 1
                if state["done"] % 25 == 0:
                    save_cache("geo_cache.json", cache)
                    save_cache("street_cache.json", street_cache)

        def osm_stage(ss, item, why):
            k, street, plz, city, center = item
            res, retry_later = None, False
            if state["can_osm"]:
                try:
                    res, w = geocode_nominatim(ss, street, plz, city, center)
                    why = join(why, w)
                except QuotaError as exc:
                    stats["abbruch"] = str(exc)
                    state["can_osm"] = False
                    why = join(why, str(exc))
                except Exception as exc:
                    why = join(why, f"OSM-Fehler: {str(exc)[:50]}")
            if res is None and state.get("can_photon", True):
                try:
                    r_ph, w_ph = geocode_photon(ss, street, plz, city, center)
                    if r_ph:
                        res, why = r_ph, ""
                    else:
                        why = join(why, w_ph)
                except QuotaError as exc:
                    state["can_photon"] = False
                    why = join(why, str(exc))
                except Exception as exc:
                    why = join(why, f"Photon-Fehler: {type(exc).__name__}")
            if res is not None and res.get("q") == "street" and hn_of(street) and center is not None and state["street_fail"] < 6:
                try:   # Straßenmitte von Photon → Overpass versucht noch die Hausnummer
                    r_ovp, _ = geocode_overpass(ss, street, center)
                    if r_ovp and r_ovp.get("q") == "addr":
                        res = r_ovp
                except Exception:
                    pass
            if res is None and center is not None and state["street_fail"] < 6:
                try:
                    r_ovp, w_ovp = geocode_overpass(ss, street, center)
                    state["street_fail"] = 0
                    if r_ovp:
                        res, why = r_ovp, ""
                    else:
                        why = join(why, w_ovp)
                except OverpassError as exc:
                    state["street_fail"] += 1
                    retry_later = True
                    why = join(why, str(exc))
                except Exception as exc:
                    why = join(why, f"Overpass-Fehler: {type(exc).__name__}")
            if res is None and center is not None and state["street_fail"] < 6:
                hit, str_why = None, ""
                try:
                    hit = resolve_street(ss, street, center, street_cache)
                    state["street_fail"] = 0
                    if not hit:
                        str_why = "Straße im PLZ-Gebiet nicht erkannt"
                except OverpassError as exc:
                    state["street_fail"] += 1
                    retry_later, str_why = True, str(exc)
                except Exception as exc:
                    state["street_fail"] += 1
                    retry_later, str_why = True, f"Straßenliste: {type(exc).__name__}"
                if hit:
                    real, hn, mid = hit
                    full = f"{real} {hn}".strip()
                    res2 = None
                    try:
                        if not state["ors_dead"]:
                            res2, _ = geocode_ors(ss, key, full, plz, "", center)
                        if res2 is None and state["can_osm"]:
                            res2, _ = geocode_nominatim(ss, full, plz, "", center)
                    except Exception:
                        res2 = None
                    if res2 is None:
                        res2 = {"lat": float(mid[0]), "lon": float(mid[1]), "q": "street", "src": "osm-strasse"}
                    res, why = {**res2, "match": full}, ""
                else:
                    why = join(why, str_why)
            elif res is None and state["street_fail"] >= 6:
                retry_later = True
                why = join(why, "Straßenabgleich übersprungen (Overpass nicht erreichbar)")
            if res is None and state["ors_dead"] and not state["can_osm"]:
                retry_later = True
            store(k, res, why, retry_later)

        def worker():
            ss = new_session()
            while True:
                job = jobs.get()
                if job is None:
                    break
                try:
                    osm_stage(ss, *job)
                except Exception as exc:
                    store(job[0][0], None, f"Fehler: {str(exc)[:60]}", True)

        th = threading.Thread(target=worker, daemon=True)
        th.start()
        sess = new_session()
        for item in todo:
            if progress:
                progress(max(0, state["done"] - 1), len(todo))
            k, street, plz, city, center = item
            res, why = None, ""
            if not state["ors_dead"]:
                try:
                    res, w = geocode_ors(sess, key, street, plz, city, center)
                    why = f"ORS: {w}" if w else ""
                except QuotaError as exc:
                    stats["abbruch"] = str(exc) + (" – weiter mit Nominatim" if state["can_osm"] else "")
                    state["ors_dead"] = True
                except Exception as exc:
                    why = f"ORS-Fehler: {str(exc)[:50]}"
            if res:
                store(k, res, "")
            else:
                jobs.put((item, why))   # Nominatim (falls verfügbar) + Overpass – Overpass hat kein Tageskontingent
        jobs.put(None)
        while th.is_alive():
            if progress:
                progress(max(0, state["done"] - 1), len(todo))
            th.join(0.5)
        save_cache("geo_cache.json", cache)
        save_cache("street_cache.json", street_cache)

    out = df.copy()
    lat, lon, gq = out["lat"].tolist(), out["lon"].tolist(), out["gq"].tolist()
    rejected = 0
    reasons: dict = {}
    for i, (street, plz, city) in enumerate(out[["Strasse", "Plz", "Ort"]].itertuples(index=False, name=None)):
        if gq[i] in ("datei", "manuell"):
            continue
        c = cache.get(addr_key(street, plz, city))
        if not c or c.get("fail"):
            if c and c.get("why"):
                reasons[c["why"]] = reasons.get(c["why"], 0) + 1
            continue
        plat, plon = lat[i], lon[i]
        if plat is not None and not pd.isna(plat) and float(haversine(plat, plon, c["lat"], c["lon"])) > GEO_MAX_DEVIATION_KM:
            rejected += 1
            continue
        lat[i], lon[i], gq[i] = c["lat"], c["lon"], c.get("q", "addr")
    out["lat"], out["lon"], out["gq"] = lat, lon, gq
    out["geo_match"] = [
        (cache.get(addr_key(st_, pz, ct)) or {}).get("match", "")
        for st_, pz, ct in out[["Strasse", "Plz", "Ort"]].itertuples(index=False, name=None)
    ]
    out["geo_grund"] = [
        (cache.get(addr_key(st_, pz, ct)) or {}).get("why", "") if g_ == "plz" else ""
        for st_, pz, ct, g_ in out[["Strasse", "Plz", "Ort", "gq"]].itertuples(index=False, name=None)
    ]
    stats["verworfen"] = rejected
    stats["gruende_gesamt"] = reasons
    return out, stats


def apply_coordinate_overrides(df: pd.DataFrame, file_bytes: bytes) -> tuple[pd.DataFrame, int]:
    ov = pd.read_csv(io.BytesIO(file_bytes), sep=None, engine="python", dtype=str, encoding="utf-8-sig")
    cols = {str(c).strip().lower(): c for c in ov.columns}

    def pick(*names):
        return next((cols[n] for n in names if n in cols), None)

    sc = pick("sap", "kundennummer", "kunde")
    la = pick("lat", "latitude", "breite", "breitengrad")
    lo = pick("lon", "lng", "longitude", "laenge", "länge", "längengrad", "laengengrad")
    if not (sc and la and lo):
        raise ValueError("Koordinaten-CSV braucht Spalten SAP, lat, lon")
    qc = pick("gq")
    coords = {}
    for _, r in ov.iterrows():
        if qc and str(r[qc]).strip().lower() == "plz":
            continue
        try:
            sap = int(float(str(r[sc]).strip()))
            la_v, lo_v = float(str(r[la]).replace(",", ".")), float(str(r[lo]).replace(",", "."))
            if not (np.isfinite(la_v) and np.isfinite(lo_v)) or not (47 <= la_v <= 56 and 5 <= lo_v <= 16):
                continue   # leer/unplausibel (außerhalb Deutschlands) → ignorieren
            coords[sap] = (la_v, lo_v)
        except Exception:
            continue
    out = df.copy()
    lat, lon, gq = out["lat"].tolist(), out["lon"].tolist(), out["gq"].tolist()
    n = 0
    for i, sap in enumerate(out["SAP"]):
        if pd.notna(sap) and int(sap) in coords:
            lat[i], lon[i] = coords[int(sap)]
            gq[i] = "manuell"
            n += 1
    out["lat"], out["lon"], out["gq"] = lat, lon, gq
    return out, n


# ---------------------------------------------------------------------------
# Adressdatei (xlsx): einziger dauerhafter Speicher für Adressen, Koordinaten und Straßenentfernungen
# ---------------------------------------------------------------------------

ADDR_SHEET, MATRIX_SHEET, HIST_SHEET = "Adressen", "Strassenmatrix", "Planungsgedaechtnis"
ADDR_COLUMNS = ["SAP", "Quelle", "Name", "Strasse_SAP", "Strasse", "Plz", "Ort", "lat", "lon", "Status", "Hinweis"]
STATUS_LABEL = {"datei": "fest (Datei)", "manuell": "fest (manuell)", "addr": "adressgenau",
                "street": "Straßenmitte", "plz": "PLZ – bitte prüfen", "geprueft": "Adresse geprüft – wird gesucht"}


LAST_HISTORY: dict = {}


def read_address_file(file_bytes: bytes, name: str = "") -> tuple[pd.DataFrame, dict]:
    """Liest die Adressdatei (xlsx oder csv). Rückgabe: Adresstabelle, Matrix-Cache {coordkey: [km, min]}.
    Ein vorhandenes Planungsgedächtnis landet in LAST_HISTORY."""
    global LAST_HISTORY
    LAST_HISTORY = {}
    matrix: dict = {}
    if name.lower().endswith(".csv"):
        adr = pd.read_csv(io.BytesIO(file_bytes), sep=None, engine="python", dtype=str, encoding="utf-8-sig")
    else:
        xl = pd.ExcelFile(io.BytesIO(file_bytes))
        adr = pd.read_excel(xl, sheet_name=ADDR_SHEET if ADDR_SHEET in xl.sheet_names else 0, dtype=str)
        if HIST_SHEET in xl.sheet_names:
            try:
                hs = pd.read_excel(xl, sheet_name=HIST_SHEET, dtype=str)
                LAST_HISTORY = json.loads("".join(hs["json"].fillna("").tolist()))
            except Exception:
                LAST_HISTORY = {}
        if MATRIX_SHEET in xl.sheet_names:
            m = pd.read_excel(xl, sheet_name=MATRIX_SHEET)
            for r in m.itertuples(index=False):
                try:
                    matrix[f"{float(r[0]):.5f},{float(r[1]):.5f}|{float(r[2]):.5f},{float(r[3]):.5f}"] = [float(r[4]), float(r[5])]
                except Exception:
                    continue
    adr.columns = [str(c).strip() for c in adr.columns]
    ren = {c: "Strasse" for c in adr.columns if c.lower() in ("straße", "strasse")}
    ren.update({c: "SAP" for c in adr.columns if c.lower() in ("sap", "kundennummer")})
    ren.update({c: "Plz" for c in adr.columns if c.lower() == "plz"})
    adr = adr.rename(columns=ren)
    if "SAP" not in adr.columns:
        raise ValueError("Adressdatei braucht eine Spalte SAP")
    adr["SAP"] = pd.to_numeric(adr["SAP"], errors="coerce").astype("Int64")
    return adr.dropna(subset=["SAP"]).drop_duplicates("SAP", keep="last"), matrix


def _num(v):
    try:
        f = float(str(v).replace(",", "."))
        return f if np.isfinite(f) else None
    except Exception:
        return None


def apply_address_file(df: pd.DataFrame, adr: pd.DataFrame, addresses: bool = True,
                       coords: bool = True) -> tuple[pd.DataFrame, int, int]:
    """Vor dem Geocoding: korrigierte Straße/PLZ/Ort übernehmen; vorhandene Koordinaten fest setzen (gq='datei')."""
    out = df.copy()
    idx = {int(s): r for s, r in zip(adr["SAP"], adr.to_dict("records"))}
    if coords:
        if "gq" not in out.columns:
            out["gq"] = None
        for col in ("lat", "lon"):
            if col not in out.columns:
                out[col] = np.nan
    n_addr = n_coord = 0
    street, plz, city = out["Strasse"].tolist(), out["Plz"].tolist(), out["Ort"].tolist()
    lat = out["lat"].tolist() if coords else []
    lon = out["lon"].tolist() if coords else []
    gq = out["gq"].tolist() if coords else []
    for i, sap in enumerate(out["SAP"]):
        r = idx.get(int(sap)) if pd.notna(sap) else None
        if not r:
            continue
        changed = False
        for lst, key in ((street, "Strasse"), (plz, "Plz"), (city, "Ort")) if addresses else ():
            v = _txt(r.get(key))
            if v and v != _txt(lst[i]):
                lst[i] = v.zfill(5) if key == "Plz" and v.isdigit() else v
                changed = True
        n_addr += changed
        if not coords or _txt(r.get("gq")).lower() == "plz":   # alte Koordinaten-CSV: PLZ-Zentren nicht festschreiben
            continue
        la, lo = _num(r.get("lat")), _num(r.get("lon"))
        if la is not None and lo is not None and 47 <= la <= 56 and 5 <= lo <= 16:
            lat[i], lon[i], gq[i] = la, lo, "datei"
            n_coord += 1
    out["Strasse"], out["Plz"], out["Ort"] = street, pd.Series(plz, dtype="string").values, city
    if coords:
        out["lat"], out["lon"], out["gq"] = lat, lon, gq
    return out, n_addr, n_coord


def build_address_workbook(geo: pd.DataFrame, original: pd.DataFrame, matrix_cache: dict,
                           prev: pd.DataFrame | None = None, history: dict | None = None) -> bytes:
    """Aktualisierte Adressdatei: alle Kunden mit bester Koordinate + Straßenmatrix (koordinatenbasiert)."""
    from openpyxl.styles import Alignment, Font, PatternFill
    orig = original.drop_duplicates("SAP").set_index("SAP")
    prev_idx = prev.set_index("SAP") if prev is not None and len(prev) else None
    rows = []
    for r in geo.drop_duplicates("SAP").itertuples(index=False):
        d = r._asdict()
        sap = d["SAP"]
        q = d.get("gq") or ""
        hint = _txt(prev_idx.loc[sap, "Hinweis"]) if prev_idx is not None and sap in prev_idx.index and "Hinweis" in prev_idx.columns else ""
        if d.get("geo_match"):
            hint = hint or f"erkannt als {d['geo_match']}"
        keep_coords = q in ("datei", "manuell", "addr", "street")
        rows.append({
            "SAP": int(sap), "Quelle": d.get("Quelle"), "Name": _txt(d.get("Name")),
            "Strasse_SAP": _txt(orig.loc[sap, "Strasse"]) if sap in orig.index else "",
            "Strasse": _txt(d.get("Strasse")), "Plz": _txt(d.get("Plz")), "Ort": _txt(d.get("Ort")),
            "lat": round(float(d["lat"]), 6) if keep_coords and pd.notna(d.get("lat")) else None,
            "lon": round(float(d["lon"]), 6) if keep_coords and pd.notna(d.get("lon")) else None,
            "Status": STATUS_LABEL.get(q, "keine Adresse" if not _txt(d.get("Strasse")) else "offen"),
            "Hinweis": hint,
        })
    adr = pd.DataFrame(rows, columns=ADDR_COLUMNS).sort_values(["Status", "Quelle", "SAP"],
                                                                  key=lambda s: s.map(lambda v: 0 if "prüfen" in str(v) or v in ("offen", "keine Adresse") else 1) if s.name == "Status" else s)
    mrows = []
    for k, v in matrix_cache.items():
        try:
            a, b = k.split("|")
            la1, lo1 = a.split(",")
            la2, lo2 = b.split(",")
            mrows.append([float(la1), float(lo1), float(la2), float(lo2), v[0], v[1]])
        except Exception:
            continue
    mat = pd.DataFrame(mrows, columns=["von_lat", "von_lon", "nach_lat", "nach_lon", "km", "min"])
    info = pd.DataFrame({"Info": [
        "Adressdatei für den Feiertags-Wochenplaner – bei jedem Lauf hochladen, danach die aktualisierte Version wieder herunterladen.",
        "Blatt Adressen: Straße/Plz/Ort überschreiben die SAP-Adresse. Sind lat/lon gefüllt, gilt die Koordinate fest (kein Geocoding).",
        "Status 'PLZ – bitte prüfen' / 'offen': Straße korrigieren ODER lat/lon eintragen (Google Maps: Rechtsklick → Koordinaten).",
        "Spalte Strasse_SAP ist nur zur Info (Original aus SAP).",
        "Blatt Strassenmatrix: LKW-Entfernungen (km) und Fahrzeiten (Min.) – nicht bearbeiten.",
        f"Erstellt: {datetime.now():%d.%m.%Y %H:%M} · {APP_BUILD}",
    ]})
    buf = io.BytesIO()
    with pd.ExcelWriter(buf, engine="openpyxl") as w:
        adr.to_excel(w, sheet_name=ADDR_SHEET, index=False)
        mat.to_excel(w, sheet_name=MATRIX_SHEET, index=False)
        info.to_excel(w, sheet_name="Info", index=False)
        if history:
            js = json.dumps(history, ensure_ascii=False, separators=(",", ":"))
            pd.DataFrame({"json": [js[i:i + 30000] for i in range(0, len(js), 30000)]}).to_excel(w, sheet_name=HIST_SHEET, index=False)
            w.sheets[HIST_SHEET].column_dimensions["A"].width = 60
        ws = w.sheets[ADDR_SHEET]
        ws.freeze_panes = "A2"
        ws.auto_filter.ref = ws.dimensions
        widths = {"A": 9, "B": 13, "C": 34, "D": 26, "E": 32, "F": 7, "G": 22, "H": 11, "I": 11, "J": 17, "K": 48}
        for col, wd in widths.items():
            ws.column_dimensions[col].width = wd
        for c in ws[1]:
            c.font = Font(bold=True)
        todo = PatternFill("solid", fgColor="FFF3C4")
        bad = PatternFill("solid", fgColor="FBE3E3")
        for row in ws.iter_rows(min_row=2):
            st_ = str(row[9].value or "")
            fill = bad if st_ in ("offen", "keine Adresse") else todo if "prüfen" in st_ else None
            if fill:
                for c in row:
                    c.fill = fill
            for c in (row[7], row[8]):
                c.number_format = "0.000000"
        w.sheets["Info"].column_dimensions["A"].width = 140
        for c in w.sheets["Info"]["A"]:
            c.alignment = Alignment(wrap_text=False)
    return buf.getvalue()


# ---------------------------------------------------------------------------
# Planungsgedächtnis: historische Feiertagspläne auswerten (Vortag/Folgetag, Zieltouren)
# ---------------------------------------------------------------------------

HIST_SHEETS = {"Direkt 1 - 99": "DIREKT", "Hupa MK 882": "MK", "Hupa 2221-4444": "HUPA_NMS", "Hupa 7773-7779": "HUPA_MALCHOW",
               "DIREKT": "DIREKT", "MK": "MK", "HUPA_NMS": "HUPA_NMS", "HUPA_MALCHOW": "HUPA_MALCHOW",
               "Direktkunden": "DIREKT", "HUPA NMS + ZAR": "HUPA_NMS", "HUPA MAL": "HUPA_MALCHOW"}
HIST_DAY_ALIAS = {"MO": "Mo", "DI": "Die", "MI": "Mitt", "DO": "Don", "FR": "Fr", "SA": "Sam",
                  "Mo": "Mo", "Die": "Die", "Mitt": "Mitt", "Don": "Don", "Fr": "Fr", "Sam": "Sam"}
HIST_ART = {"DIREKT": "DIREKT", "MK": "MK", "HUPA NMS": "HUPA_NMS", "HUPA ZAR": "HUPA_NMS", "HUPA MAL": "HUPA_MALCHOW",
            "HUPA MALCHOW": "HUPA_MALCHOW"}


def _parse_plan_sheet(raw: pd.DataFrame, quelle: str | None) -> pd.DataFrame | None:
    """Kopfzeile suchen (Zeile mit ≥4 Wochentagen + Nr/SAP) – deckt alte und neue Formate ab."""
    hr, dated = None, False
    is_date = lambda v: bool(re.fullmatch(r"\d{1,2}\.\d{1,2}\.?(\d{2,4})?", v))
    for i in range(min(8, len(raw))):
        vals = [str(v).strip() for v in raw.iloc[i].tolist()]
        if not any(v in ("Nr", "CSB") or v.startswith("SAP") for v in vals):
            continue
        if sum(v in HIST_DAY_ALIAS for v in vals) >= 4:
            hr = i
            break
        if sum(is_date(v) for v in vals[:20]) >= 5:   # Kopf mit Datumsangaben '29.10.' … statt Wochentagen
            hr, dated = i, True
            break
    if hr is None:
        return None
    col = {}
    hdr = [str(v).strip() for v in raw.iloc[hr].tolist()]
    if dated:
        first = next(i for i, v in enumerate(hdr) if is_date(v))
        for j, d in enumerate(DAY_COLUMNS):
            if first + j < len(hdr) and is_date(hdr[first + j]):
                col[d] = first + j
    for i, h in enumerate(hdr):
        if h in HIST_DAY_ALIAS and HIST_DAY_ALIAS[h] not in col:
            col[HIST_DAY_ALIAS[h]] = i
        elif h in ("Nr", "CSB") and "CSB" not in col:
            col["CSB"] = i
        elif h.startswith("SAP") and "SAP" not in col:
            col["SAP"] = i
        elif h == "Art" and "Art" not in col:
            col["Art"] = i
    d = pd.DataFrame({k: raw.iloc[hr + 1:, i].values for k, i in col.items()})
    if quelle is None:
        if "Art" not in d:
            return None
        d["Quelle"] = d["Art"].astype(str).str.strip().str.upper().map(HIST_ART)
    else:
        d["Quelle"] = quelle
    for k in DAY_COLUMNS + ["CSB", "SAP"]:
        d[k] = pd.to_numeric(d[k], errors="coerce") if k in d.columns else np.nan
    d = d[(d["CSB"].notna() | d["SAP"].notna()) & d["Quelle"].notna()]
    return d[["Quelle", "CSB", "SAP", *DAY_COLUMNS]]


def load_plan_any(file_bytes: bytes) -> pd.DataFrame:
    """Liest Wochen-/Feiertagspläne in allen bekannten Formaten: aktuelle Quelldatei, alte Blätter
    ('Direkt 1 - 99' …, Spalte 'Nr' = CSB), 'Direktkunden'/'HUPA MAL' und Einblatt-Listen mit Spalte 'Art'."""
    xl = pd.ExcelFile(io.BytesIO(file_bytes))
    out = []
    for sheet in xl.sheet_names:
        single = len(xl.sheet_names) == 1 or str(sheet).upper().startswith("KW")
        if sheet not in HIST_SHEETS and not single:
            continue
        raw = pd.read_excel(xl, sheet_name=sheet, header=None)
        if raw.empty:
            continue
        d = _parse_plan_sheet(raw, HIST_SHEETS.get(sheet))
        if d is not None and len(d):
            out.append(d)
    if not out:
        raise ValueError("keine Tourenblätter gefunden")
    return pd.concat(out, ignore_index=True)


def plan_date(file_bytes: bytes):
    """Letzte Speicherung laut Office-Metadaten – dient zum Paaren von Plänen aus derselben Zeit."""
    try:
        import zipfile
        core = zipfile.ZipFile(io.BytesIO(file_bytes)).read("docProps/core.xml").decode("utf-8", "ignore")
        m = re.search(r"<dcterms:modified[^>]*>(\d{4}-\d{2}-\d{2})", core)
        return pd.Timestamp(m.group(1)) if m else None
    except Exception:
        return None


def _detect_outage(h: pd.DataFrame, n: pd.DataFrame):
    """Ausfalltag = Tag, dessen Kunden (laut Normalplan n) im Plan h fehlen und/oder auf Nachbartage wandern."""
    m = h.merge(n, on="k", suffixes=("", "_n"))
    best, best_score = None, 0
    for i, d in enumerate(DAY_COLUMNS):
        nb = [DAY_COLUMNS[j] for j in (i - 1, i + 1) if 0 <= j < len(DAY_COLUMNS)]
        isd = m[d + "_n"].notna()
        aff = m[isd]
        if not len(aff):
            continue
        score = 0
        for x in nb:   # neue Lieferungen am Nachbartag – müssen fast nur Kunden dieses Tages betreffen
            add = m[x].notna() & (m[x + "_n"].isna() | (m[x] != m[x + "_n"]))
            score += int((add & isd).sum()) - 2 * int((add & ~isd).sum())
        if aff[d].isna().mean() > 0.8:
            score += len(aff)
        wiped = aff[d].isna().mean() > 0.8
        if h[d].notna().sum() < 0.05 * max(1, n[d].notna().sum()):   # Spalte komplett geleert = eindeutig
            score += 10 * len(aff)
        # nicht geleerte Spalte: mind. 30 % der Kunden muss auf Nachbartage gewandert sein
        if not wiped and score < 0.3 * len(aff):
            continue
        if score > best_score:
            best, best_score = d, score
    return (best if best_score >= 25 else None), m


def analyze_history(base: pd.DataFrame, files: list) -> tuple[dict, list]:
    """files: [(name, bytes)]. Ergebnis: {Ausfalltag: {'tours': {Quelle|Tour: {prev,next,both,cov,tt:{Tag|Tour:n}}},
    'sap': {Quelle|SAP: {prev,next}}, 'files': [...]}} + Protokoll.
    Normalplan je Datei: ein anderer hochgeladener Plan aus derselben Zeit (±21 Tage), in dem der Ausfalltag
    normal beliefert wird (z. B. Karfreitag ↔ Ostermontag); sonst die aktuelle Quelldatei.
    Jüngere Pläne zählen stärker (Disponenten übernehmen meist den Vorjahresplan)."""
    import hashlib
    b = base[["Quelle", "SAP", "CSB", *DAY_COLUMNS]].copy()
    plans, log, seen = [], [], set()
    for name, data in files:
        hsh = hashlib.md5(data).hexdigest()
        if hsh in seen:
            log.append({"Datei": name, "Ausfalltag": "–", "Kunden": 0, "Hinweis": "doppelt hochgeladen – übersprungen"})
            continue
        seen.add(hsh)
        try:
            plans.append({"name": name, "df": load_plan_any(data), "date": plan_date(data)})
        except Exception as exc:
            log.append({"Datei": name, "Ausfalltag": "–", "Kunden": 0, "Hinweis": f"nicht lesbar: {exc}"})
    # CSB → SAP (alte Pläne ohne SAP-Spalte)
    c2s = {}
    for d in [b] + [p["df"] for p in plans]:
        for c, sp in d.loc[d["CSB"].notna() & d["SAP"].notna(), ["CSB", "SAP"]].itertuples(index=False):
            c2s.setdefault(int(c), int(sp))
    def keyed(d):
        d = d.copy()
        d["SAP"] = d["SAP"].fillna(d["CSB"].map(lambda c: c2s.get(int(c)) if pd.notna(c) else np.nan))
        d = d[d["SAP"].notna()]
        d["k"] = d["SAP"].astype("int64")
        return d.drop_duplicates("k")
    bk = keyed(b)
    base_q = dict(zip(bk["k"], bk["Quelle"]))
    for p in plans:
        p["df"] = keyed(p["df"])
        p["out"], _ = _detect_outage(p["df"], bk)
    hist: dict = {}
    for p in plans:
        name, h, best = p["name"], p["df"], p["out"]
        if not best:
            log.append({"Datei": name, "Ausfalltag": "–", "Kunden": len(h), "Hinweis": "kein Ausfalltag erkennbar"})
            continue
        # Normalplan aus derselben Zeit suchen
        normal, nname = bk, "aktuelle Quelldatei"
        if p["date"] is not None:
            cands = [q for q in plans if q is not p and q["date"] is not None and abs((q["date"] - p["date"]).days) <= 21
                     and q["out"] != best and q["df"][best].notna().sum() >= 0.7 * max(1, bk[best].notna().sum())]
            if cands:
                q = min(cands, key=lambda q: abs((q["date"] - p["date"]).days))
                normal, nname = q["df"], q["name"]
        m = h.merge(normal, on="k", suffixes=("", "_n"))
        i = DAY_COLUMNS.index(best)
        prev = DAY_COLUMNS[i - 1] if i > 0 else None
        nxt = DAY_COLUMNS[i + 1] if i + 1 < len(DAY_COLUMNS) else None
        # jüngere Pläne zählen mehr: Gewicht verdoppelt sich je Halbjahr (Disponenten kopieren meist den letzten Plan)
        w = round(2 ** ((p["date"] - pd.Timestamp("2020-01-01")).days / 182.5), 3) if p["date"] is not None else 0.5
        H = hist.setdefault(best, {"tours": {}, "sap": {}, "files": []})
        H["files"].append(name)
        cnt = {"prev": 0, "next": 0, "both": 0, "cov": 0}
        def moved(r, d):
            return bool(d and pd.notna(r[d]) and (pd.isna(r[d + "_n"]) or r[d] != r[d + "_n"]))
        for r in m[m[best + "_n"].notna()].to_dict("records"):
            np_, nn_ = moved(r, prev), moved(r, nxt)
            kind = "both" if np_ and nn_ else "prev" if np_ else "next" if nn_ else "cov"
            cnt[kind] += 1
            q = base_q.get(r["k"], r["Quelle_n"])
            T = H["tours"].setdefault(f"{q}|{int(r[best + '_n'])}", {"prev": 0, "next": 0, "both": 0, "cov": 0, "tt": {}})
            T[kind] = round(T[kind] + w, 2)
            for side_day, flag in ((prev, np_), (nxt, nn_)):
                if flag:
                    k2 = f"{side_day}|{int(r[side_day])}"
                    T["tt"][k2] = round(T["tt"].get(k2, 0) + w, 2)
            if kind != "cov":
                S = H["sap"].setdefault(f"{q}|{int(r['k'])}", {"prev": 0, "next": 0, "tt": {}})
                S.setdefault("tt", {})
                if kind in ("prev", "both"):
                    S["prev"] = round(S["prev"] + w, 2)
                if kind in ("next", "both"):
                    S["next"] = round(S["next"] + w, 2)
                for side_day, flag in ((prev, np_), (nxt, nn_)):
                    if flag:
                        k2 = f"{side_day}|{int(r[side_day])}"
                        S["tt"][k2] = round(S["tt"].get(k2, 0) + w, 3)
        log.append({"Datei": name, "Ausfalltag": best, "Kunden": int(m[best + "_n"].notna().sum()),
                    "Hinweis": f"Vortag {cnt['prev']} · Folgetag {cnt['next']} · beide {cnt['both']} · "
                               f"entfallen/abgedeckt {cnt['cov']} · Normalplan: {nname}"
                               + (f" · Stand {p['date']:%m/%Y}" if p["date"] is not None else "")})
    return hist, log


def merge_history(a: dict, b: dict) -> dict:
    out = json.loads(json.dumps(a or {}))
    for day, H in (b or {}).items():
        O = out.setdefault(day, {"tours": {}, "sap": {}, "files": []})
        O["files"] = list(dict.fromkeys(O.get("files", []) + H.get("files", [])))
        for k, T in H.get("tours", {}).items():
            X = O["tours"].setdefault(k, {"prev": 0, "next": 0, "both": 0, "cov": 0, "tt": {}})
            for f in ("prev", "next", "both", "cov"):
                X[f] = X.get(f, 0) + T.get(f, 0)
            for k2, n in T.get("tt", {}).items():
                X["tt"][k2] = X["tt"].get(k2, 0) + n
        for k, S in H.get("sap", {}).items():
            X = O["sap"].setdefault(k, {"prev": 0, "next": 0, "tt": {}})
            X["prev"] += S.get("prev", 0)
            X["next"] += S.get("next", 0)
            X.setdefault("tt", {})
            for k2, n in S.get("tt", {}).items():
                X["tt"][k2] = X["tt"].get(k2, 0) + n
    return out


def build_nodes(df: pd.DataFrame) -> tuple[pd.DataFrame, list, dict]:
    out = df.copy()
    nodes = [DEPOT_LATLON]
    index: dict = {}
    node_col = []
    for lat, lon in zip(out["lat"], out["lon"]):
        if lat is None or lon is None or pd.isna(lat) or pd.isna(lon):
            node_col.append(None)
            continue
        k = (round(float(lat), 5), round(float(lon), 5))
        if k not in index:
            index[k] = len(nodes)
            nodes.append(k)
        node_col.append(index[k])
    out["node"] = pd.Series(node_col, dtype="object").values
    node_src: dict = defaultdict(set)
    for n, q in zip(node_col, out["Quelle"]):
        if n is not None:
            node_src[n].add(q)
    return out, nodes, node_src


def needed_pairs(nodes: list, node_src: dict, k: int) -> set:
    """Depot↔alle Knoten plus die k nächsten Nachbarn je Startbereich (beide Richtungen)."""
    arr = np.array(nodes, dtype=float)
    pairs = set()
    for n in node_src:
        pairs.add((0, n))
        pairs.add((n, 0))
    by_q: dict = defaultdict(list)
    for n, qs in node_src.items():
        for q in qs:
            by_q[q].append(n)
    for ids in by_q.values():
        if len(ids) < 2:
            continue
        ids = np.array(sorted(ids))
        sub = arr[ids]
        dm = haversine(sub[:, 0][:, None], sub[:, 1][:, None], sub[:, 0][None, :], sub[:, 1][None, :])
        kk = min(k, len(ids) - 1)
        nn = np.argsort(dm, axis=1)[:, 1:kk + 1]
        for r, row in enumerate(nn):
            a = int(ids[r])
            for c in row:
                b = int(ids[c])
                pairs.add((a, b))
                pairs.add((b, a))
    return pairs


def _ckey(nodes: list, i: int, j: int) -> str:
    return f"{nodes[i][0]:.5f},{nodes[i][1]:.5f}|{nodes[j][0]:.5f},{nodes[j][1]:.5f}"


def _matrix_batches(missing: dict, nodes: list) -> list:
    batches = []
    S: list = []
    D: set = set()
    for s in sorted(missing, key=lambda n: (round(nodes[n][0] * 5), nodes[n][1])):
        dests = missing[s]
        if len(dests) > MATRIX_MAX_ELEMENTS:
            dl = sorted(dests)
            for i in range(0, len(dl), MATRIX_MAX_ELEMENTS):
                batches.append(([s], set(dl[i:i + MATRIX_MAX_ELEMENTS])))
            continue
        nd = D | dests
        if S and (len(S) + 1) * len(nd) > MATRIX_MAX_ELEMENTS:
            batches.append((S, D))
            S, nd = [], set(dests)
        S.append(s)
        D = nd
    if S:
        batches.append((S, D))
    return batches


def fetch_matrix(nodes: list, pairs: set, key: str = "", max_requests: int = 450,
                 progress: Callable[[int, int], None] | None = None,
                 profile: str = "driving-hgv") -> tuple[dict, dict, dict]:
    cache_name = f"matrix_cache_{profile}.json"
    cache = load_cache(cache_name)
    missing: dict = defaultdict(set)
    for i, j in pairs:
        if _ckey(nodes, i, j) not in cache:
            missing[i].add(j)
    stats = {"anfragen": 0, "neu": 0, "fehlend": sum(len(v) for v in missing.values()), "abbruch": ""}
    if missing and key:
        import requests
        sess = requests.Session()
        sess.headers.update({"Content-Type": "application/json", "User-Agent": HTTP_UA})
        batches = _matrix_batches(missing, nodes)
        for bi, (S, D) in enumerate(batches):
            if stats["anfragen"] >= max_requests:
                stats["abbruch"] = f"Anfragelimit {max_requests} erreicht – Rest beim nächsten Lauf"
                break
            if progress:
                progress(bi, len(batches))
            dl = sorted(D)
            loc = list(dict.fromkeys(list(S) + dl))
            pos = {n: i for i, n in enumerate(loc)}
            body = {
                "locations": [[nodes[n][1], nodes[n][0]] for n in loc],
                "sources": [pos[s] for s in S], "destinations": [pos[d] for d in dl],
                "metrics": ["distance", "duration"], "units": "km",
            }
            try:
                r = ors_request(sess, "POST", "matrix", key, profile=profile, json=body, timeout=90)
            except Exception as exc:
                stats["abbruch"] = f"Netzwerkfehler: {exc}"
                break
            if r.status_code in (401, 403, 429):
                stats["abbruch"] = f"OpenRouteService Matrix: HTTP {r.status_code}"
                break
            if r.status_code >= 400:
                stats["abbruch"] = f"OpenRouteService Matrix: HTTP {r.status_code} {r.text[:160]}"
                break
            js = r.json()
            dists, durs = js.get("distances") or [], js.get("durations") or []
            for si, s in enumerate(S):
                for di, d in enumerate(dl):
                    if s == d:
                        continue
                    try:
                        km, sec = dists[si][di], durs[si][di]
                    except (IndexError, TypeError):
                        continue
                    if km is None or sec is None:
                        continue
                    ck = _ckey(nodes, s, d)
                    if ck not in cache and d in missing.get(s, ()):
                        stats["neu"] += 1
                    cache[ck] = [round(float(km), 2), round(float(sec) / 60.0, 1)]
            stats["anfragen"] += 1
            if stats["anfragen"] % 10 == 0:
                save_cache(cache_name, cache)
            time.sleep(1.6)
        save_cache(cache_name, cache)

    mat, ratios, speeds = {}, [], []
    for i, j in pairs:
        v = cache.get(_ckey(nodes, i, j))
        if not v:
            continue
        mat[f"{i},{j}"] = v
        air = float(haversine(nodes[i][0], nodes[i][1], nodes[j][0], nodes[j][1]))
        if air >= 2 and v[1] > 0:
            ratios.append(v[0] / air)
            speeds.append(v[0] / (v[1] / 60.0))
    net = {
        "factor": round(float(np.clip(np.median(ratios), 1.05, 2.0)), 3) if len(ratios) >= 20 else DEFAULT_ROAD_FACTOR,
        "kmh": round(float(np.clip(np.median(speeds), 25, 90)), 1) if len(speeds) >= 20 else DEFAULT_KMH,
        "pairs": len(mat), "needed": len(pairs),
    }
    stats["fehlend"] = len(pairs) - len(mat)
    return mat, net, stats


def _match_keys(df: pd.DataFrame) -> pd.DataFrame:
    out = df.copy()
    out["_k"] = (
        out["Quelle"].astype(str) + "|" + out["SAP"].astype("Int64").astype(str) + "|"
        + out["CSB"].astype("Int64").astype(str)
    )
    out["_occ"] = out.groupby("_k").cumcount()
    return out


def attach_reference(df: pd.DataFrame, ref_bytes: bytes) -> tuple[pd.DataFrame, int]:
    """Hängt den Referenzplan (gleiche Blattstruktur) je Kundenzeile als REF-Tage an.
    Abgleich über Blatt + SAP + CSB (+ laufende Nummer bei Mehrfachzeilen)."""
    try:
        ref = read_source(ref_bytes)
    except Exception:   # altes Format ('Direkt 1 - 99' …)
        ref = load_plan_any(ref_bytes)
        ref["SAP"] = ref["SAP"].astype("Int64")
        ref["CSB"] = ref["CSB"].astype("Int64")
    ref = _match_keys(ref)
    base = _match_keys(df)
    lookup = {
        (k, o): {d: json_ready(v) for d, v in zip(DAY_COLUMNS, vals)}
        for k, o, *vals in ref[["_k", "_occ", *DAY_COLUMNS]].itertuples(index=False, name=None)
    }
    refs = [lookup.get((k, o)) for k, o in zip(base["_k"], base["_occ"])]
    base["REF"] = refs
    matched = sum(1 for r in refs if r is not None)
    return base.drop(columns=["_k", "_occ"]), matched


def make_payload(df: pd.DataFrame) -> list[dict]:
    keep = [
        "uid", "Quelle", "source_row", "excel_row", "CSB", "SAP", "Name", "Strasse", "Plz", "Ort",
        *DAY_COLUMNS,
        *[f"LRF_{d}" for d in DAY_COLUMNS], *[f"LRFROW_{d}" for d in DAY_COLUMNS],
        "lat", "lon", "Lieferinfo", "Zeitkritisch", "node", "gq",
    ]
    df = df.copy()
    if "node" not in df.columns:
        df["node"] = None
    if "gq" not in df.columns:
        df["gq"] = np.where(df["lat"].notna(), "plz", None)
    has_ref = "REF" in df.columns
    rows = []
    for rec in df[keep + (["REF"] if has_ref else [])].to_dict("records"):
        row = {k: json_ready(v) for k, v in rec.items() if k != "REF"}
        if has_ref and isinstance(rec.get("REF"), dict):
            row["REF"] = rec["REF"]
        rows.append(row)
    return rows


def excel_col_letter(index_1_based: int) -> str:
    out, n = "", index_1_based
    while n:
        n, rem = divmod(n - 1, 26)
        out = chr(65 + rem) + out
    return out


def get_day_column_map(file_bytes: bytes) -> dict[str, dict[str, str]]:
    result: dict[str, dict[str, str]] = {}
    for sheet in SHEETS:
        headers = list(pd.read_excel(io.BytesIO(file_bytes), sheet_name=sheet, nrows=0).columns)
        normalized = ["Strasse" if str(x) == "Straße" else str(x) for x in headers]
        result[sheet] = {}
        for day in DAY_COLUMNS:
            if day not in normalized:
                raise ValueError(f"{sheet}: Spalte {day} fehlt")
            result[sheet][day] = excel_col_letter(normalized.index(day) + 1)
    return result


# ---------------------------------------------------------------------------
# HTML
# ---------------------------------------------------------------------------

def _js(obj) -> str:
    return json.dumps(obj, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")


def _fill(template: str, mapping: dict[str, str]) -> str:
    pattern = re.compile("__(" + "|".join(sorted(map(re.escape, mapping), key=len, reverse=True)) + ")__")
    return pattern.sub(lambda m: mapping[m.group(1)], template)


def build_html(customers, tour_starts, source_name, source_xlsx, day_col_map,
               info_name="", starts_name="", ref_name="", matrix=None, net=None, history=None) -> str:
    aux = " · ".join(x for x in [info_name, starts_name, (f"Referenz: {ref_name}" if ref_name else "")] if x)
    return _fill(HTML_TEMPLATE, {
        "SRC": escape(source_name),
        "AUX": escape((" · " + aux) if aux else ""),
        "GENERATED": datetime.now().strftime("%d.%m.%Y %H:%M"),
        "JSZIP": JSZIP_B64,
        "CUSTOMERS": _js(customers),
        "TOUR_STARTS": _js(tour_starts),
        "SOURCE_B64": base64.b64encode(source_xlsx).decode("ascii"),
        "SOURCE_NAME": _js(source_name),
        "DAY_COLS": _js(day_col_map),
        "HAS_REF": "true" if ref_name else "false",
        "REF_NAME": _js(ref_name),
        "MATRIX": _js(matrix or {}),
        "HISTORY": _js(history or {}),
        "NET": _js(net or {"factor": DEFAULT_ROAD_FACTOR, "kmh": DEFAULT_KMH, "pairs": 0, "needed": 0}),
    })


